import{_ as a,o as n,c as t,a2 as e}from"./chunks/framework.CvydjLy7.js";const _=JSON.parse('{"title":"一、先确认你在用哪个版本","description":"","frontmatter":{"title":"一、先确认你在用哪个版本"},"headers":[{"level":3,"title":"方法一：查 Maven 中央仓库（最可靠）","slug":"方法一-查-maven-中央仓库-最可靠","link":"#方法一-查-maven-中央仓库-最可靠","children":[]},{"level":3,"title":"方法二：看本地实际生效的版本","slug":"方法二-看本地实际生效的版本","link":"#方法二-看本地实际生效的版本","children":[]},{"level":3,"title":"本教程的版本基线","slug":"本教程的版本基线","link":"#本教程的版本基线","children":[]}],"relativePath":"ch00/01.md","filePath":"ch00/01.md","lastUpdated":1789497795000}'),p={name:"ch00/01.md"};function i(l,s,d,r,o,c){return n(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="一、先确认你在用哪个版本" tabindex="-1">一、先确认你在用哪个版本 <a class="header-anchor" href="#一、先确认你在用哪个版本" aria-label="Permalink to &quot;一、先确认你在用哪个版本&quot;">​</a></h1><p>“最新版本是多少”这个问题，靠博客和搜索引擎得到的答案经常是过时的。可靠的做法只有三个：查 Maven 中央仓库的元数据、看官方文档站、看本地实际依赖。</p><h3 id="方法一-查-maven-中央仓库-最可靠" tabindex="-1">方法一：查 Maven 中央仓库（最可靠） <a class="header-anchor" href="#方法一-查-maven-中央仓库-最可靠" aria-label="Permalink to &quot;方法一：查 Maven 中央仓库（最可靠）&quot;">​</a></h3><p>Maven 中央仓库为每个构件维护一个 <code>maven-metadata.xml</code>，里面有 <code>&lt;latest&gt;</code> 与 <code>&lt;release&gt;</code> 两个字段。以 <code>spring-boot-starter-parent</code> 为例：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://repo1.maven.org/maven2/org/springframework/boot/spring-boot-starter-parent/maven-metadata.xml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -oE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&lt;(latest|release)&gt;[^&lt;]*&#39;</span></span></code></pre></div><p>本机实际执行的结果：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>latest&gt;4.2.0-M1</span></span>
<span class="line"><span>release&gt;4.2.0-M1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 最近若干个版本号</span></span>
<span class="line"><span>4.1.0-M1</span></span>
<span class="line"><span>4.1.0-M2</span></span>
<span class="line"><span>4.1.0-M3</span></span>
<span class="line"><span>4.1.0-M4</span></span>
<span class="line"><span>4.1.0-RC1</span></span>
<span class="line"><span>4.1.0</span></span>
<span class="line"><span>4.1.1</span></span>
<span class="line"><span>4.2.0-M1</span></span></code></pre></div><blockquote><p><strong>这里有个坑，很多人被它误导</strong></p><p><code>&lt;release&gt;</code> 字段<strong>并不代表稳定版</strong>，它只表示“最新发布的版本”，里程碑版（<code>-M1</code>）和候选版（<code>-RC1</code>）同样会被写进去。所以上例中 <code>&lt;release&gt;</code> 是 <code>4.2.0-M1</code>，但当前<strong>稳定版（GA）是 4.1.1</strong>。</p><p>判断法则很简单：<strong>版本号里不带 <code>-M</code>、<code>-RC</code>、<code>-SNAPSHOT</code> 后缀的才是 GA</strong>。生产项目请用 GA 版本；里程碑版适合提前体验新特性，不建议上生产。</p></blockquote><h3 id="方法二-看本地实际生效的版本" tabindex="-1">方法二：看本地实际生效的版本 <a class="header-anchor" href="#方法二-看本地实际生效的版本" aria-label="Permalink to &quot;方法二：看本地实际生效的版本&quot;">​</a></h3><p>工程建起来之后，判断“我到底在用哪个版本”最直接的办法是看启动日志和依赖树。Spring Boot 启动时会打印一整套版本信息：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 依赖树：看 Spring Boot 与各 starter 的实际版本</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dependency:tree</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Dincludes=org.springframework.boot</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 启动日志：看运行期各组件版本（本机实测片段）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/activity-server-1.0.0.jar</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  .   ____          _            __ _ _</span></span>
<span class="line"><span> /\\\\ / ___&#39;_ __ _ _(_)_ __  __ _ \\ \\ \\ \\</span></span>
<span class="line"><span>( ( )\\___ | &#39;_ | &#39;_| | &#39;_ \\/ _\` | \\ \\ \\ \\</span></span>
<span class="line"><span> \\\\/  ___)| |_)| | | | | || (_| |  ) ) ) )</span></span>
<span class="line"><span>  &#39;  |____| .__|_| |_| |_| |_\\__, | / / / /</span></span>
<span class="line"><span> =========|_|==============|___/=/_/_/_/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:: Spring Boot ::                (v4.1.1)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>INFO --- [activity-server] : HHH000001: Hibernate ORM core version 7.4.5.Final</span></span>
<span class="line"><span>INFO --- [activity-server] : Tomcat started on port 8080 (http) with context path &#39;/&#39;</span></span>
<span class="line"><span>INFO --- [activity-server] : Started ActivityServerApplication in 4.069 seconds</span></span></code></pre></div><p>启动日志里的这几行信息量很大：Spring Boot 版本、Hibernate 版本、内嵌容器与端口、启动耗时。写文档或做技术方案时，把它截图放进附件，比写“我用的是最新版”可信得多。</p><h3 id="本教程的版本基线" tabindex="-1">本教程的版本基线 <a class="header-anchor" href="#本教程的版本基线" aria-label="Permalink to &quot;本教程的版本基线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>版本</th><th>说明</th></tr></thead><tbody><tr><td>Spring Boot</td><td><strong>4.1.1</strong></td><td>当前 GA，2026-08 发布</td></tr><tr><td>3.5 维护线</td><td>3.5.16</td><td>老项目升级过渡用，仍在维护</td></tr><tr><td>开发版</td><td>4.2.0-M1</td><td>里程碑版，含未稳定特性，不用于本教程</td></tr><tr><td>JDK</td><td>21（LTS）</td><td>官方要求 17 及以上，兼容至 26</td></tr><tr><td>Maven</td><td>3.9.11</td><td>官方要求 3.6.3 及以上</td></tr></tbody></table>`,15)])])}const g=a(p,[["render",i]]);export{_ as __pageData,g as default};
